-- Тема 3: Предупреждающие знаки — топик id=3, категория id=2
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(2,3,'На каком расстоянии от опасного участка вне населённого пункта устанавливаются предупреждающие знаки, если в самом знаке не указано другое расстояние?',
'["50–100 м","150–300 м","500–700 м","900–1000 м"]'::jsonb,1,
'Вне населённых пунктов предупреждающие знаки устанавливаются на расстоянии 150–300 м до начала опасного участка, если конкретное расстояние не указано на табличке под знаком.',1),
(2,3,'Что означает предупреждающий знак Дети?',
'["Приближение к образовательному учреждению, возможно появление детей на дороге","Запрет проезда для детей","Место остановки школьного автобуса","Пешеходный переход только для детей"]'::jsonb,0,
'Знак Дети предупреждает о приближении к участку дороги вблизи детского учреждения, где возможно появление детей на проезжей части.',2),
(2,3,'Что означает предупреждающий знак Скользкая дорога?',
'["Проезжая часть может быть скользкой в мокром или загрязнённом состоянии","Дорога всегда покрыта льдом","Требуется объезд по обочине","Дорога закрыта для движения"]'::jsonb,0,
'Знак Скользкая дорога предупреждает о том, что покрытие дороги в этом месте может стать скользким, особенно в мокром состоянии, что требует снижения скорости.',3),
(2,3,'Что означает знак Неровная дорога?',
'["Наличие резких неровностей на проезжей части (выбоины, повреждения)","Отсутствие асфальтового покрытия","Крутой спуск","Сужение дороги"]'::jsonb,0,
'Знак Неровная дорога предупреждает о наличии на проезжей части резких неровностей: выбоин, волнообразности, вспучивания.',4),
(2,3,'Что означает знак Пересечение с круговым движением?',
'["Впереди перекрёсток с круговым движением","Разворот запрещён","Место разворота","Круговая парковка"]'::jsonb,0,
'Знак Пересечение с круговым движением информирует о приближении к перекрёстку, на котором организовано круговое движение.',5),
(2,3,'Что означает предупреждающий знак Дикие животные?',
'["Возможен выход диких животных на дорогу","Запрещена охота на данном участке","Заповедная зона","Ферма поблизости"]'::jsonb,0,
'Знак Дикие животные предупреждает об участке дороги, на котором возможен выход на проезжую часть диких животных.',6),
(2,3,'На каком расстоянии в населённых пунктах устанавливаются предупреждающие знаки перед опасным участком, если иное не указано табличкой?',
'["50–100 м","150–300 м","500 м","10–20 м"]'::jsonb,0,
'В населённых пунктах предупреждающие знаки устанавливаются на расстоянии 50–100 м до начала опасного участка, если конкретное расстояние не указано на табличке 8.1.1.',7),
(2,3,'Что означает знак Железнодорожный переезд без шлагбаума?',
'["Впереди нерегулируемый переезд, водитель должен убедиться в отсутствии поезда","Переезд закрыт","Переезд только для пешеходов","Переезд регулируется только светофором"]'::jsonb,0,
'Знак предупреждает о приближении к железнодорожному переезду, не оборудованному шлагбаумом — водитель обязан особо убедиться в безопасности проезда.',8),
(2,3,'Что означает предупреждающий знак Опасный поворот с изображением одной стрелки?',
'["Дорога поворачивает в направлении, указанном стрелкой, с малым радиусом закругления","Разворот запрещён","Впереди перекрёсток","Обгон запрещён"]'::jsonb,0,
'Знак Опасный поворот предупреждает о повороте дороги малого радиуса или с ограниченной видимостью в направлении, указанном на знаке.',9),
(2,3,'Что означает предупреждающий знак Падение камней?',
'["Возможен неожиданный выход камней или грунта на проезжую часть","Дорога засыпана камнями","Требуется объезд","Стройка на дороге"]'::jsonb,0,
'Знак Падение камней предупреждает об участке дороги, на котором возможны обвалы, оползни или падение камней на проезжую часть.',10);

-- Тема 4: Запрещающие знаки — топик id=4, категория id=2
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(2,4,'Что означает знак Въезд запрещён?',
'["Запрещён въезд всех ТС в данном направлении","Запрещён только въезд грузовиков","Одностороннее движение","Главная дорога"]'::jsonb,0,
'Знак 3.1 Въезд запрещён запрещает въезд всех транспортных средств в данном направлении, за исключением маршрутных ТС.',1),
(2,4,'На какое время действует знак Ограничение максимальной скорости?',
'["До ближайшего перекрёстка или до отменяющего знака","На весь населённый пункт независимо от перекрёстков","На 500 метров","Бессрочно на весь маршрут"]'::jsonb,0,
'Зона действия знака 3.24 распространяется от места установки знака до ближайшего перекрёстка, а в населённом пункте — до конца населённого пункта, если не установлен отменяющий знак 3.25.',2),
(2,4,'Что означает знак Обгон запрещён?',
'["Запрещён обгон любых ТС, кроме тихоходных, гужевых повозок, мопедов, двухколёсных мотоциклов без коляски","Запрещено движение легковых автомобилей","Запрещена остановка","Разрешён только правый поворот"]'::jsonb,0,
'Знак 3.20 запрещает обгон всех транспортных средств, кроме тихоходных ТС, гужевых повозок, велосипедов, мопедов и двухколёсных мотоциклов без коляски.',3),
(2,4,'Что означает знак Движение запрещено?',
'["Запрещено движение всех ТС в обоих направлениях","Запрещён только пешеходный переход","Ограничение по высоте","Направление объезда"]'::jsonb,0,
'Знак 3.2 Движение запрещено запрещает движение всех транспортных средств в обоих направлениях.',4),
(2,4,'Что означает знак Ограничение максимальной массы?',
'["Запрещено движение ТС, включая прицепы, общая масса которых больше указанной","Запрещён проезд грузовиков независимо от массы","Ограничение по ширине","Знак информационный, не запрещающий"]'::jsonb,0,
'Знак 3.11 запрещает движение ТС, в том числе с прицепом, общая фактическая масса которых больше указанной на знаке.',5),
(2,4,'Действует ли знак Стоянка запрещена только на нечётные числа месяца, если это не указано на табличке?',
'["Да, всегда только на нечётные числа","Нет, знак действует постоянно, если нет уточняющей таблички","Знак действует только по будням","Знак действует только ночью"]'::jsonb,1,
'Знак 3.28 Стоянка запрещена действует постоянно на всей зоне действия, если не установлена уточняющая табличка с указанием дней, часов или чётности дат.',6),
(2,4,'Что означает знак Ограничение высоты?',
'["Запрещено движение ТС, габаритная высота которых с грузом или без груза превышает указанную","Ограничение только по массе","Знак разрешает объезд по эстакаде","Разрешён проезд только пешеходам"]'::jsonb,0,
'Знак 3.13 запрещает движение ТС, габаритная высота которых с грузом или без груза больше значения, указанного на знаке.',7),
(2,4,'Где заканчивается зона действия знака Обгон запрещён, установленного вне перекрёстка?',
'["У ближайшего перекрёстка либо у отменяющего знака Конец зоны запрещения обгона","Действует до конца населённого пункта в любом случае","Действие ограничено 100 метрами","Не имеет ограничения зоны действия"]'::jsonb,0,
'Зона действия знака 3.20 распространяется от места установки знака до ближайшего перекрёстка, а при отсутствии перекрёстка — до знака 3.21, отменяющего его действие.',8),
(2,4,'Что означает знак Движение механических транспортных средств запрещено?',
'["Запрещено движение всех механических ТС, кроме мопедов","Разрешено движение только мотоциклов","Запрещено движение только грузовиков","Ограничение скорости для механических ТС"]'::jsonb,0,
'Знак 3.3 запрещает движение механических ТС, за исключением мопедов.',9);
